    i = 0
    while i < len(s):
        ch = s[i]
        if ch == '\\' and i + 1 < len(s) and s[i + 1] == ';':
            current.append(';')
            i += 2
        elif ch == ';':
            pairs.append(''.join(current))
            current = []
            i += 1
        else:
            current.append(ch)
            i += 1
    pairs.append(''.join(current))

    result = {}
    for pair in pairs:
        pair = pair.strip()
        if not pair:
            continue
        idx = pair.find('=')
        if idx == -1:
            continue
        key = pair[:idx].strip()
        value = pair[idx + 1:].strip()
        result[key] = value
    return result

